import { profile } from "../data/profile.js";
let timer;
export function toast(message) {
  let el = document.querySelector("#toast");
  if (!el) {
    el = document.createElement("div");
    el.id = "toast";
    el.className = "toast";
    el.setAttribute("role", "status");
    document.body.append(el);
  }
  el.textContent = message;
  el.classList.add("visible");
  clearTimeout(timer);
  timer = setTimeout(() => el.classList.remove("visible"), 3200);
}
export async function copyText(text, message) {
  try {
    await navigator.clipboard.writeText(text);
    toast(message);
  } catch {
    const dialog = document.createElement("dialog");
    dialog.className = "copy-dialog";
    const heading = document.createElement("p");
    heading.textContent = profile.ui.copyFailed;
    const field = document.createElement("textarea");
    field.value = text;
    field.readOnly = true;
    field.setAttribute("aria-label", profile.ui.citation);
    const close = document.createElement("button");
    close.className = "button";
    close.textContent = profile.ui.close;
    close.onclick = () => dialog.close();
    dialog.append(heading, field, close);
    document.body.append(dialog);
    dialog.addEventListener("close", () => dialog.remove());
    dialog.showModal();
    field.select();
  }
}
