// Live oscilloscope strip under the navigation bar: a modulated RF carrier
// with a travelling pulse (CH1, phosphor) and its reflection (CH2, amber),
// drawn with phosphor persistence. Readouts sweep across the band.
import { register, pixelRatio, colors, motionAllowed } from "./core/manager.js";
import { profile } from "../data/profile.js";

let instance;

export function init(container, options = {}) {
  destroy();
  const host = container.querySelector(".scope-canvas");
  const left = container.querySelector("[data-scope-left]");
  const right = container.querySelector("[data-scope-right]");
  const canvas = document.createElement("canvas");
  host.append(canvas);
  const ctx = canvas.getContext("2d");
  let w = 1,
    h = 1,
    time = 0,
    lastLabel = -1;

  const trace = (t, amp, freq, speed, color, width, blur, delay = 0) => {
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.shadowColor = color;
    ctx.shadowBlur = blur;
    ctx.beginPath();
    const mid = h * 0.58;
    const packet = ((t * speed + delay) % 1.6) - 0.3;
    for (let x = 0; x <= w; x += 2) {
      const u = x / w;
      const env =
        0.18 +
        0.82 * Math.exp(-(((u - packet) * 7) ** 2)) +
        0.08 * Math.sin(u * 9 + t * 0.7);
      const y =
        mid -
        amp *
          env *
          Math.sin(u * freq * Math.PI * 2 - t * 9 + Math.sin(u * 3 + t) * 0.6);
      x ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
    }
    ctx.stroke();
    ctx.shadowBlur = 0;
  };

  const render = (t, dt, still) => {
    time = t;
    const c = colors();
    const phase = still && !motionAllowed() ? 3.2 : t;
    // Phosphor persistence: fade the previous frame instead of clearing.
    ctx.globalCompositeOperation = "destination-out";
    ctx.fillStyle = `rgba(0,0,0,${still ? 1 : 0.32})`;
    ctx.fillRect(0, 0, w, h);
    ctx.globalCompositeOperation = "lighter";
    // Graticule ticks
    ctx.fillStyle = c.line;
    for (let i = 1; i < 20; i++) ctx.fillRect((w * i) / 20, h - 5, 1, 5);
    trace(phase, h * 0.2, 26, 0.18, c.amber, 1, 4, 0.8);
    trace(phase, h * 0.34, 34, 0.25, c.phosphor, 1.4, 10);
    ctx.globalCompositeOperation = "source-over";
    if (left && right && (still || Math.floor(t * 3) !== lastLabel)) {
      lastLabel = Math.floor(t * 3);
      const sweep = (phase * 0.05) % 1;
      const f = 4 + 4 * sweep;
      const s11 = -4 - 26 * Math.exp(-(((f - 5.8) / 0.55) ** 2));
      const labels = profile.diagrams.lab;
      left.textContent = `${labels.channel} ${f.toFixed(2)} ${labels.frequencyUnit} · ${labels.voltageScale}`;
      right.textContent = `${labels.reflection} ${s11.toFixed(1)} ${labels.db} · ${labels.illustrative}`;
    }
  };

  const resize = new ResizeObserver(() => {
    w = Math.max(1, container.clientWidth);
    h = Math.max(1, container.clientHeight);
    const dpr = pixelRatio();
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    canvas.style.width = `${w}px`;
    canvas.style.height = `${h}px`;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    render(time, 0, true);
  });
  resize.observe(container);
  const stop = register(container, render, options);
  instance = {
    destroy() {
      stop();
      resize.disconnect();
      canvas.remove();
    },
  };
  return instance;
}

export function destroy() {
  instance?.destroy();
  instance = null;
}
