import { profile } from "../data/profile.js";
import { icon } from "./icons.js";
import { logo } from "./logo.js";
import { esc } from "./utils.js";
import { initThemeToggle } from "./themeToggle.js";
import { motionAllowed, toggleMotion } from "../animations/core/manager.js";
export function nav(page) {
  return `<a class="skip-link" href="#main">${esc(profile.ui.skip)}</a><header class="site-header"><div class="nav-inner"><a class="brand" href="./index.html" aria-label="${esc(profile.name)}">${logo()}</a><nav id="main-nav" aria-label="${esc(profile.ui.primaryNav)}">${profile.nav.map((link) => `<a href="${link.href}" ${page === link.id ? 'aria-current="page"' : ""}>${link.label}</a>`).join("")}</nav><div class="nav-controls"><button id="motion-toggle" class="icon-button" type="button">${icon("wave")}</button><button id="theme-toggle" class="icon-button" type="button" aria-label="${esc(profile.ui.theme)}">${icon("sun")}</button><button id="menu-toggle" class="icon-button" type="button" aria-controls="main-nav" aria-expanded="false" aria-label="${esc(profile.ui.menu)}">${icon("menu")}</button></div></div></header>`;
}
export function initNav() {
  initThemeToggle(document.querySelector("#theme-toggle"));
  const motion = document.querySelector("#motion-toggle");
  const sync = () => {
    motion.setAttribute("aria-pressed", String(motionAllowed()));
    motion.setAttribute(
      "aria-label",
      motionAllowed() ? profile.ui.motionOn : profile.ui.motionOff,
    );
    motion.title = motion.getAttribute("aria-label");
  };
  motion.addEventListener("click", toggleMotion);
  document.addEventListener("motionchange", sync);
  sync();
  const menu = document.querySelector("#menu-toggle"),
    header = document.querySelector(".site-header");
  const close = () => {
    menu.setAttribute("aria-expanded", "false");
    header.classList.remove("menu-open");
  };
  menu.addEventListener("click", () => {
    const open = menu.getAttribute("aria-expanded") !== "true";
    menu.setAttribute("aria-expanded", String(open));
    header.classList.toggle("menu-open", open);
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && header.classList.contains("menu-open")) {
      close();
      menu.focus();
    }
  });
  document.addEventListener("click", (event) => {
    if (!header.contains(event.target)) close();
  });
  document
    .querySelectorAll("#main-nav a")
    .forEach((link) => link.addEventListener("click", close));
}
