import { profile } from "../data/profile.js";
import { icon } from "./icons.js";
export const esc = (value) =>
  String(value ?? "").replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        c
      ],
  );
export const profileLinks = () =>
  profile.profiles
    .filter((p) => /^https:\/\//.test(p.url))
    .map(
      (p) =>
        `<a class="profile-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(p.name)}" title="${esc(p.name)}">${icon(p.icon)}<span>${esc(p.name)}</span></a>`,
    )
    .join("");
export const heading = (eyebrow, title, extra = "") =>
  `<div class="section-heading"><div><p class="eyebrow">${esc(eyebrow)}</p><h2>${esc(title)}</h2></div>${extra}</div>`;
export const sortedPublications = () =>
  [...profile.publications].sort(
    (a, b) =>
      Number(!!b.forthcoming) - Number(!!a.forthcoming) ||
      (b.year || 0) - (a.year || 0),
  );
export const interestCards = (full = false) =>
  profile.interests
    .map(
      (item, i) =>
        `<article class="interest-card motion-item"><div class="interest-top">${icon(item.icon)}<span class="index">0${i + 1}</span></div><h3>${esc(item.title)}</h3>${item.badge ? `<span class="badge red">${esc(item.badge)}</span>` : ""}${full ? `<p>${esc(item.description)}</p>` : ""}</article>`,
    )
    .join("");
