import "../styles/base.css";
import "../styles/lab.css";
import { profile } from "../data/profile.js";
import { nav, initNav } from "../components/nav.js";
import { footer } from "../components/footer.js";
import { initCitations } from "../components/pubCard.js";
import { init as initMicro } from "../animations/micro.js";
import {
  init as initField,
  destroy as destroyField,
} from "../animations/labBackdrop.js";
import {
  init as initScope,
  destroy as destroyScope,
} from "../animations/scopeStrip.js";
import { esc } from "../components/utils.js";
const disposers = [];
export function boot(page, markup) {
  document.querySelector("#app").innerHTML =
    `${nav(page)}<main id="main" tabindex="-1">${markup}</main>${footer()}`;
  initNav();
  initCitations(document.querySelector("main"));
  initMicro(document.querySelector("main"), {
    enabled: profile.animations.micro,
  });
  // Full-page electromagnetic field behind every page.
  const field = document.createElement("div");
  field.className = "lab-field";
  field.setAttribute("aria-hidden", "true");
  document.body.prepend(field);
  initField(field, { enabled: profile.animations.backdrop !== false });
  disposers.push(() => {
    destroyField();
    field.remove();
  });
  // Live oscilloscope strip under the navigation bar.
  const header = document.querySelector(".site-header");
  header.insertAdjacentHTML(
    "beforeend",
    `<div class="scope-strip" aria-hidden="true"><div class="scope-canvas"></div><span class="scope-label scope-left" data-scope-left></span><span class="scope-label scope-right" data-scope-right></span></div>`,
  );
  initScope(header.querySelector(".scope-strip"), {
    enabled: profile.animations.scope !== false,
  });
  disposers.push(destroyScope);
}
export function pageHero(page, visual) {
  const p = page === "publications" ? profile.publicationsPage : profile[page];
  return `<section class="page-hero container"><div class="hero-copy"><p class="eyebrow page-kicker">${esc(p.eyebrow)}</p><h1>${esc(p.title)}</h1><p>${esc(p.description)}</p></div><div class="page-visual" data-model-label="${esc(profile.diagrams.lab.model)}">${visual}</div></section>`;
}
export function scene(id, label, cls = "") {
  return `<div id="${id}" class="scene ${cls}" role="img" aria-label="${esc(label)}"></div>`;
}
export function lazyScene(id, load, key) {
  const el = document.getElementById(id);
  if (!el) return;
  const observer = new IntersectionObserver(
    async (entries) => {
      if (!entries.some((e) => e.isIntersecting)) return;
      observer.disconnect();
      const module = await load();
      module.init(el, { enabled: profile.animations[key] });
      disposers.push(() => module.destroy());
    },
    { rootMargin: "180px" },
  );
  observer.observe(el);
  disposers.push(() => observer.disconnect());
}
window.addEventListener("pagehide", (event) => {
  if (!event.persisted) disposers.forEach((fn) => fn());
});
