import { profile } from "../data/profile.js";
import { esc } from "./utils.js";
import { icon } from "./icons.js";
import { copyText } from "./toast.js";
export function pubCard(p, index, compact = false) {
  return `<article class="pub-card ${compact ? "compact" : ""}" data-id="${esc(p.id)}"><span class="pub-number">${String(index + 1).padStart(2, "0")}</span><div class="pub-body"><div class="pub-meta"><span>${esc(p.type)}</span><span class="meta-separator">/</span><span class="${p.forthcoming ? "badge" : ""}">${p.year || profile.ui.forthcoming}</span>${p.sci ? `<span class="badge">${profile.ui.sci}</span>` : ""}${p.firstAuthor ? `<span class="badge red">${profile.ui.firstAuthor}</span>` : ""}${p.forthcoming && p.year ? `<span class="badge">${profile.ui.forthcoming}</span>` : ""}</div><h3>${esc(p.title)}</h3><p class="authors">${p.authors.map((a) => (a === "B. Raut" ? `<strong>${esc(a)}</strong>` : esc(a))).join(", ")}</p><p class="venue">${esc(p.venue)}${p.details ? `, ${esc(p.details)}` : ""}</p><div class="pub-bottom"><span class="citation-count">${p.citations == null ? profile.ui.citationUnknown : `${p.citations} ${profile.ui.citations}`}</span><div class="pub-actions"><button class="text-button cite-button" data-cite="${esc(p.id)}">${icon("copy")}${profile.ui.cite}</button>${p.doi ? `<a class="doi-link" href="https://doi.org/${esc(p.doi)}" target="_blank" rel="noopener noreferrer" aria-label="${esc((compact ? profile.ui.doi : p.doi) + ": " + p.title)}"><span>${compact ? profile.ui.doi : esc(p.doi)}</span>${icon("arrow")}</a>` : `<span class="mono doi-pending">${profile.ui.doiPending}</span>`}</div></div></div></article>`;
}
export function initCitations(root) {
  root.addEventListener("click", (event) => {
    const button = event.target.closest("[data-cite]");
    if (!button) return;
    const p = profile.publications.find((p) => p.id === button.dataset.cite);
    const citation = `${p.authors.join(", ")}. ${p.title} ${p.venue}${p.details ? ", " + p.details : ""}${p.year ? ", " + p.year : ". " + profile.ui.forthcoming}.${p.doi ? " https://doi.org/" + p.doi : ""}`;
    copyText(citation, profile.ui.citationCopied);
  });
}
